<?php use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V;
$cats = ['' => 'Todas']; foreach (H::categories() as $c) { $cats[$c['id']] = $c['name']; }
$agents = ['' => 'Todos', 'none' => 'Sem responsável']; foreach (H::agents() as $a) { $agents[$a['user_id']] = trim($a['first_name'] . ' ' . $a['last_name']); } ?>
<div class="cms-card"><?php if ($showFilters): ?><form class="cms-filters" method="get"><?= V::field('Protocolo, assunto ou e-mail', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::TICKET_STATUS]) ?><?= V::field('Prioridade', 'priority', $filters['priority'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::PRIORITIES]) ?><?= V::field('Categoria', 'category', $filters['category'], ['type' => 'select', 'choices' => $cats]) ?><?= V::field('Responsável', 'assignee', $filters['assignee'], ['type' => 'select', 'choices' => $agents]) ?><?= V::field('Prazo', 'overdue', $filters['overdue'], ['type' => 'select', 'choices' => ['' => 'Todos', '1' => 'Vencidos']]) ?><button class="cms-btn">Filtrar</button></form><?php endif; ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum chamado encontrado.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Chamados"><table><thead><tr><th>Protocolo</th><th>Assunto</th><th>Cliente</th><th>Categoria</th><th>Prioridade</th><th>Situação</th><th>Responsável</th><th>Atividade</th></tr></thead><tbody><?php foreach ($result['rows'] as $t): ?><tr><td><a href="/chamados/<?= (int) $t['id'] ?>"><?= V::e($t['protocol']) ?></a></td><td><?= V::e($t['subject']) ?></td><td><?= V::e($t['requester_email']) ?></td><td><?= V::e($t['category_name']) ?></td><td><?= V::badge($t['priority'], V::PRIORITIES[$t['priority']] ?? $t['priority']) ?></td><td><?= V::badge($t['status'], V::TICKET_STATUS[$t['status']] ?? $t['status']) ?></td><td><?= V::e($t['assignee_name'] ?? '—') ?></td><td><?= V::date($t['last_activity_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
